(116, NULL, '', 'SKANDI BUZIOS', 'Porto do Açu', '{"grupo":"TECHNIP\/DOF","unidade":"SKANDI BUZIOS","data":"2026-05-13","local":"Porto do Açu","modal":"Portuário ","preposto":"Pablo Cruz ","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"16","m1":"00","label2":"Real","h2":"16","m2":"11"}],"embarque_previsto":"17:00","embarque_real":"18:33","atendimento_inicio":"15:53","atendimento_fim":"18:54"},"info_troca":"<div><span style=\"-webkit-text-size-adjust: 100%; font-size: 1rem; -webkit-tap-highlight-color: transparent;\">Informo que houve uma divergência na logística de desembarque dos colaboradores da DOF. A colaboradora Cristina seguiria para o Rio de Janeiro, porém foi direcionada para Campos. Já o colaborador Jhony desembarcaria no trevo de Macaé, mas o veículo também está seguindo com destino a Campos.<\/span><br><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\"><br><\/span><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\">Foram direcionados dois veículos para o Rio de Janeiro, com 3 colaboradores em cada, e um veículo com o colaborador Jhony para Campos. O colaborador solicita liberação para que o carro siga até Macaé.<\/span><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\"><br><\/span><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\">Foi realizado contato com a logística e com o analista Vítor, porém até o momento não obtivemos retorno.<\/span><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\"><br><\/span><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\">Os colaboradores seguiram viagem, e o colaborador Jhony está seguindo destino para Campos, aguardando retorno da logística quanto à liberação do veículo para seguir até Macaé.<\/span><\/div>","pax_embarcando":"TFMC\n1 DANIEL SERRA\n2 FABIO BAPTISTA MANSUR\n3 GABRIEL DE OLIVEIRA BARBOSA\n4 RENZO NEVES DO CARMO PINK\n5 RONALDO FUSCO JUNIOR\n6 WEVERTON DE MENEZES ALMEIDA\n7 WALLACE ALVES PAIXAO\n8 WELLINGTON CUNHA ROCHA\n9 DERVYLIONE CONCAVES DA CONCEIÇÃO\n10 DIEGO SANTOS RIBEIRO\n11 FABIANO ANDRADE GOMES\n12 FERNANDO DE ARAUJO CORDEIRO\n13 RENATO BRAGA PEREIRA\n14 ROGERIO ANDRE VIEIRA DE OLIVEIRA\n15 TAYRONI NASCIMENTO DANTAS\n16 RODRIGO MATHIAS\n17 SUZANE DE QUEIROZ SILVA\n\nDOF\n1 MARIA ISABEL TAVARES COSTA\n2 GUSTAVO VARGAS MACHADO\n3 CLEYTON RAMOS VITALINO\n4 EDUARDO MATHIAS DE MEDEIROS E ALBUQUERQUE\n5 VINICIUS CHAVES DOS SANTOS\n6 RENAN DOMINGOS SANTOS DA SILVA\n7 JOSE CARLOS DE OLIVEIRA\n","pax_desembarcando":"TFMC\n1 ALEXANDRE ANDRADE DA SILVA\n2 ROBSON RIBEIRO DE SOUZA\n3 BRUNO PITTA PESSANHA\n4 CLEITON DA SILVA\n5 REIVISON DIAS DE CARVALHO\n6 RODRIGO ANDRE DE SOUZA\n7 HAWLLISON BRUNO DIAS DE CARVALHO\n8 IVAN LUIS CARNEIRO DOS SANTOS\n9 ROGERIO DA SILVA COSTA\n10 RAFAEL DE MEDEIROS BELLARMINDO\n11 VINICIUS SACRAMENTO NOGUEIRA\n12 JHONATAN DA SILVA DOS SANTOS\n13 JOSE RICARDO JUNIO CAMARGO BATISTA\n14 RONDIMAR DA SILVA FERREIRA\n15 RENAN AMARAL LEITE\n16 VINICIUS ANTONIO DE OLIVEIRA FERREIRA\n\nDOF\n1 CRISTINA GUEDES BASTOS VILLA\n2 THALES LUCAS SICUPIRA\n3 GLEBSON FERREIRA SANTOS\n4 ARTHUR WENDERSON SANTOS PINTO\n5 ROGERIO DANTAS FELIPE\n6 RAMON DOS ANJOS CASSIANO\n7 JHONY MAIA RIBEIRO\n","fotos":[]}', 0, NULL, '2026-05-14 15:20:36', '2026-07-10 10:05:16', 'TECHNIP', NULL, NULL, '2804:1b3:9301:74a6:1d2e:8108:10ba:5a68'),
(117, NULL, '', 'SKANDI VITORIA', 'Porto do Açu', '{"grupo":"TECHNIP\/DOF","unidade":"SKANDI VITORIA","data":"2026-05-14","local":"Porto do Açu","modal":"Portuário ","preposto":"Pablo Cruz ","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"07","m1":"00","label2":"Real","h2":"07","m2":"26"}],"embarque_previsto":"08:30","embarque_real":"09:38","atendimento_inicio":"06:16","atendimento_fim":"10:08"},"info_troca":"<div><br><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\">Atraso no embarque devido a movimentação no terminal.<\/span><\/div><div><br><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\">Informo o embarque do colaborador Reinaldo Da Silva Leitão Junior antecipadamente às &nbsp;08:13.<\/span><\/div><div><span style=\"-webkit-text-size-adjust: 100%;\">E o embarque posteriormente do colaborador Sidney da Silva Carvalho às 10:07.<\/span><\/div>","pax_embarcando":"TFMC:\n1 GABRIEL BRIZOLA GOMES\n2 RAFAEL PEREIRA TOSTES\n3 DENYS PESSANHA DOS SANTOS\n4 DENNERSON FIGUEIREDO HENRIQUE\n5 LEONARDO BENEDITO NICOLINI\n\nDOF:\n6 REINALDO DA SILVA LEITAO JUNIOR \n\nTERCEIRIZADOS:\n7 PATRICK SOUZA DE ALENCAR\n8 TIAGO JOÃO DA SILVA MATOS VIEIRA MENDES\n","pax_desembarcando":"TFMC:\n1 MARIANA AMELIA ROMAO GOMES\n2 RAFAELL FERNANDO DE ALMEIDA\n3 FABIANO HENRIQUE TEIXEIRA DE SOUZA\n4 LUIZ EDUARDO CARDOSO BITA\n5 BRUNO DA SILVA ROSA GARCIA\n6 THIAGO CANTANHEDE ROSENDO DOS SANTOS\n7 FELIPE VITORIO NASCIMENTO DE ALMEIDA\n\n","fotos":[]}', 0, NULL, '2026-05-14 15:36:47', '2026-07-10 10:05:16', 'TECHNIP', NULL, NULL, '179.144.164.142');
